b['questions'][15]['assumptions']=['Robot heading is fixed, range is nonzero, and bearing derivatives use radians.']
for n in [9,12,13,14,15,16,25,29,30,32,33,34,35,47,57,61,62,64,68,70,71,72]:
 q=b['questions'][n-1]
 if q['type']=='numerical' and not q['solution']['formulas']:
  q['solution']['formulas']=[{'expression':'See the explicitly stated model and worked steps.','variables':{'inputs':'All numerical inputs are specified in the stem.'},'units':{'result':'Units are stated in the stem and answer options.'},'assumptions':q['assumptions']}]
